<?php
declare(strict_types=1);require_once __DIR__.'/../config/api.php';if($_SERVER['REQUEST_METHOD']!=='GET')respond(['success'=>false,'message'=>'Method not allowed'],405);$u=requireUser($pdo);$from=trim((string)($_GET['from']??''));$to=trim((string)($_GET['to']??''));$where='p.user_id=?';$params=[$u['user_id']];if($from!==''){$where.=' AND p.payment_date>=?';$params[]=$from;}if($to!==''){$where.=' AND p.payment_date<=?';$params[]=$to;}$s=$pdo->prepare("SELECT p.id,p.job_id,p.amount,p.payment_date,p.payment_method,p.transaction_reference,p.notes,j.status job_status,v.title,h.name hotel_name FROM payments p LEFT JOIN jobs j ON j.id=p.job_id LEFT JOIN vacancies v ON v.id=j.vacancy_id LEFT JOIN hotels h ON h.id=j.hotel_id WHERE $where ORDER BY p.payment_date DESC,p.id DESC");$s->execute($params);$rows=$s->fetchAll(PDO::FETCH_ASSOC);$total=0;foreach($rows as $r)$total+=(float)$r['amount'];respond(['success'=>true,'data'=>['total_earnings'=>$total,'payments'=>$rows]]);
